from pathlib import Path
from html import escape
from urllib.parse import quote
import json, re, textwrap

ROOT=Path(__file__).parent
OUT=ROOT/'site'
DOMAIN='https://ristrutturazioniformia.it'
BRAND='Ristrutturazioni Formia'
NAV=[('Ristrutturare casa','ristrutturare-casa'),('Rifare il bagno','ristrutturazione-bagno'),('Da vasca a doccia','vasca-in-doccia'),('Costi','costi-ristrutturazione')]

def href(slug=''):
    return '/' + (slug+'/' if slug else '')

def icon(kind):
    icons={
        'arrow':'<path d="M4 11h15m-6-6 6 6-6 6"/>',
        'check':'<path d="m4 11 4 4 12-11"/>',
        'ruler':'<path d="M4 18h16V6H4v12Zm4-8v4m4-4v4m4-4v4"/>',
        'file':'<path d="M7 3h7l5 5v13H7zM14 3v6h5M10 13h6m-6 4h6"/>',
        'home':'<path d="m3 11 9-8 9 8M6 9v12h12V9M10 21v-7h4v7"/>',
        'water':'<path d="M12 2c2 4 7 9 7 13a7 7 0 0 1-14 0c0-4 5-9 7-13Z"/>',
        'compass':'<path d="M12 2a10 10 0 1 1 0 20 10 10 0 0 1 0-20Zm4 6-2 6-6 2 2-6z"/>',
        'menu':'<path d="M4 7h16M4 12h16M4 17h16"/>'}
    return f'<svg aria-hidden="true" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="square" stroke-linejoin="miter">{icons.get(kind,icons["arrow"])}</svg>'

def anchor(slug,label, cls='link-arrow'):
    return f'<a class="{cls}" href="{href(slug)}">{label}{icon("arrow")}</a>'

def section_label(n, txt):
    return f'<p class="eyebrow"><span>{n}</span> {txt}</p>'

def page(title, description, content, slug='',active='',schema_type='WebPage'):
    url=DOMAIN+href(slug)
    nav=''.join(f'<a href="{href(p)}" {"aria-current=\"page\"" if active==p else ""}>{l}</a>' for l,p in NAV)
    breadcrumbs= ('<nav class="breadcrumb wrap" aria-label="Percorso"><a href="/">Home</a><span aria-hidden="true">/</span><span>'+escape(title.split('|')[0].strip())+'</span></nav>') if slug else ''
    data={'@context':'https://schema.org','@type':schema_type,'name':title.split('|')[0].strip(),'description':description,'url':url,'inLanguage':'it-IT','isPartOf':{'@type':'WebSite','name':BRAND,'url':DOMAIN}}
    legal_notice='<div class="aff-disclosure">Questo è un portale informativo indipendente, non un’impresa edile. Il servizio di preventivi sarà gestito dal partner esterno Edilnet; un futuro collegamento affiliato potrebbe generare una commissione per il sito, senza costi aggiuntivi per l’utente.</div>'
    layout=f'''<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#151919">
<meta name="description" content="{escape(description,quote=True)}"><title>{escape(title,quote=False)} | Ristrutturazioni Formia</title>
<link rel="canonical" href="{url}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><meta property="og:type" content="website"><meta property="og:locale" content="it_IT"><meta property="og:title" content="{escape(title,quote=True)} | Ristrutturazioni Formia"><meta property="og:description" content="{escape(description,quote=True)}"><meta property="og:url" content="{url}"><link rel="stylesheet" href="/assets/site.css">
<script type="application/ld+json">{json.dumps(data,ensure_ascii=False).replace('</','<\\/')}</script></head>
<body><a class="skip" href="#main">Salta al contenuto</a><div class="preview-strip">ANTEPRIMA DI PROGETTO &mdash; il sito pubblico non è stato modificato</div>
<div class="utility"><div class="wrap"><span>GUIDA INDIPENDENTE · FORMIA E GOLFO DI GAETA</span><span>RICERCA / CONFRONTO / DECISIONE</span></div></div>
<header class="site-header"><div class="wrap header-inner">
<a href="/" class="brand" aria-label="Ristrutturazioni Formia — Home"><span class="brand-mark" aria-hidden="true"><span></span><span></span><span></span></span><span class="brand-type">RISTRUTTURAZIONI<strong>FORMIA<span class="brand-dot">.</span></strong></span></a>
<nav class="site-nav" id="site-nav" aria-label="Navigazione principale">{nav}<a class="nav-proposals" href="/preventivi/">Preventivi {icon('arrow')}</a></nav>
<button class="menu-toggle" type="button" aria-expanded="false" aria-controls="site-nav" aria-label="Apri menu">{icon('menu')}</button></div></header>
{breadcrumbs}<main id="main">{content}</main>
<section class="prefooter"><div class="wrap prefooter-inner"><div><span class="eyebrow light">IL PUNTO DI PARTENZA</span><h2>Progetti chiari.<br><em>Scelte migliori.</em></h2></div><div><p>Prima una guida utile. Poi preventivi confrontabili. Nessuna promessa inventata.</p><a href="/preventivi/" class="btn btn-light">Come confrontare preventivi {icon('arrow')}</a></div></div></section>
<footer class="footer"><div class="wrap footer-main"><div><a href="/" class="footer-brand">RISTRUTTURAZIONI <b>FORMIA.</b></a><p>Contenuti informativi per orientarsi nei lavori in casa, con attenzione al territorio. Non eseguiamo lavori né effettuiamo sopralluoghi.</p></div><div class="footer-links"><span>ESPLORA</span><a href="/ristrutturare-casa/">Ristrutturare casa</a><a href="/ristrutturazione-bagno/">Rifare il bagno</a><a href="/vasca-in-doccia/">Da vasca a doccia</a><a href="/costi-ristrutturazione/">Costi e preventivi</a></div><div class="footer-links"><span>INFORMAZIONI</span><a href="/metodo/">Il metodo</a><a href="/preventivi/">Servizio preventivi</a><a href="/privacy/">Privacy della preview</a></div></div><div class="wrap footer-bottom">{legal_notice}<div class="footer-meta"><span>© 2026 Ristrutturazioni Formia · Demo non pubblicata</span><a href="#main">Torna su ↑</a></div></div></footer>
<script src="/assets/site.js" defer></script></body></html>'''
    target=OUT/(slug or '.')
    target.mkdir(parents=True,exist_ok=True)
    (target/'index.html').write_text(layout,encoding='utf-8')

def header(k,title,lead,subtitle):
    return f'''<section class="page-hero wrap">{section_label(k,subtitle)}<h1>{title}</h1><p class="page-lede">{lead}</p></section>'''

def checklist(items):
    return '<ul class="checklist">'+''.join(f'<li><span class="check-icon">{icon("check")}</span>{i}</li>' for i in items)+'</ul>'

def tiles(items):
    return '<div class="tiles">'+''.join(f'<article class="tile"><div class="tile-num">{i+1:02}</div><h3>{t}</h3><p>{b}</p><a href="{href(slug)}" aria-label="Approfondisci: {escape(t,quote=True)}">Leggi la guida {icon("arrow")}</a></article>' for i,(t,b,slug) in enumerate(items))+'</div>'

hero_drawing='''<svg class="building-svg" viewBox="0 0 660 620" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Disegno architettonico stilizzato di un ambiente in prospettiva"><defs><pattern id="grid" width="22" height="22" patternUnits="userSpaceOnUse"><path d="M22 0H0V22" fill="none" stroke="#fff" stroke-opacity=".08" stroke-width=".7"/></pattern></defs><rect width="660" height="620" fill="url(#grid)"/><g fill="none" stroke="#d7e5dd" stroke-width="2" stroke-linejoin="miter"><path d="M120 387L318 272l215 125-197 117z"/><path d="M120 387V179l198-106v199M318 272V73l215 106v218M533 397V179M120 179l198 115 215-115"/><path d="M188 216l71-38v138l-71 40z"/><path d="M192 228l63-34M192 348l63-33" stroke-opacity=".6"/><path d="M372 132l101 55v122l-101-57z"/><path d="M381 143v100l85 49V196z" stroke-opacity=".65"/><path d="M318 294v218" stroke-dasharray="5 8" stroke-opacity=".55"/><path d="M251 335l82 48 71-43-83-46zM251 335v76l82 47v-75M333 458l71-40v-78"/><path d="M342 350v67M260 345v64" stroke-opacity=".6"/></g><g fill="none" stroke="#eebf9e" stroke-width="2"><path d="M90 149v260M80 149h20M80 409h20M120 554h416M120 544v20M536 544v20"/><path d="M109 482l220 130M104 476l9 13M329 602l6 15"/></g><g fill="#eebf9e" font-family="monospace" font-size="12" letter-spacing="2"><text x="82" y="138">A—A</text><text x="292" y="580">SEZIONE 01</text><text x="429" y="160">02</text></g><g fill="#f1e8db" font-family="Arial,sans-serif" font-size="12"><text x="130" y="65" letter-spacing="3">ARCHITETTURA / INTERVENTI / SPAZI</text></g></svg>'''

home=f'''<section class="hero"><div class="wrap hero-grid"><div class="hero-copy">{section_label('01 / 06','LA GUIDA PER PARTIRE')}<h1>Ristrutturare,<br><span>con criterio.</span></h1><p class="hero-lede">Casa, bagno, doccia. Prima di chiedere un preventivo, metti a fuoco le lavorazioni, i costi e le decisioni che contano davvero.</p><div class="hero-actions"><a href="/ristrutturare-casa/" class="btn btn-primary">Inizia dalla guida {icon('arrow')}</a><a href="/costi-ristrutturazione/" class="text-link">Come si calcolano i costi <span>↗</span></a></div><div class="hero-rule"><span>EDITORIALE INDIPENDENTE</span><span>FORMIA · GAETA · GOLFO</span></div></div><div class="hero-visual">{hero_drawing}<div class="visual-stamp"><span>PROGETTO</span><strong>PRIMA.</strong><span>PREVENTIVO</span><strong>POI.</strong></div></div></div></section>
<section class="stats"><div class="wrap stats-inner"><div><span class="stat-n">01</span><p>Un percorso pratico<br><strong>prima dei lavori</strong></p></div><div><span class="stat-n">03</span><p>Interventi principali<br><strong>da confrontare</strong></p></div><div><span class="stat-n">0</span><p>Preventivi inventati<br><strong>o imprese fittizie</strong></p></div></div></section>
<section class="section wrap" id="guide">{section_label('02','SCEGLI IL TUO INTERVENTO')}<div class="section-row"><h2>Un progetto.<br>Le domande giuste.</h2><p>Non tutte le ristrutturazioni partono dallo stesso punto. Abbiamo separato le scelte per aiutarti a definire il lavoro prima di confrontare offerte.</p></div>{tiles([('Ristrutturare casa','Dall’impianto elettrico alle finiture: priorità, fasi e punti da chiarire con i professionisti.','ristrutturare-casa'),('Rifare il bagno','Demolizioni, impermeabilizzazione, impianti e materiali: la checklist prima dei preventivi.','ristrutturazione-bagno'),('Sostituire la vasca','Misure, accessibilità, scarichi e posa: le domande essenziali prima di scegliere la doccia.','vasca-in-doccia')])}</section>
<section class="midband"><div class="wrap midband-grid"><div>{section_label('03','PRIMA I NUMERI')}<h2>Un costo al metro quadro <em>non basta.</em></h2><p>La stessa superficie può richiedere interventi molto diversi. Scopri cosa determina il prezzo e costruisci uno scenario basato sulle tue ipotesi, senza cifre spacciate per preventivi.</p>{anchor('costi-ristrutturazione','Esplora costi e simulatore','btn btn-outline')}</div><div class="budget-visual" aria-hidden="true"><div class="budget-top"><span>PROSPETTO DI SPESA</span><b>01 / 04</b></div><div class="budget-bars"><div><span>DEMOLIZIONI</span><i style="--w:48%"></i></div><div><span>IMPIANTI</span><i style="--w:79%"></i></div><div><span>FINITURE</span><i style="--w:64%"></i></div><div><span>IMPREVISTI</span><i style="--w:28%"></i></div></div><div class="budget-bottom">LE VOCI, NON UN PREZZO INVENTATO <span>↗</span></div></div></div></section>
<section class="section wrap"><div class="section-row">{section_label('04','DAL TERRITORIO AL CANTIERE')}<h2>Formia non è<br>una keyword.</h2><p>È il contesto in cui si trova la casa: accessi, condizioni dell’immobile, edificio, disponibilità delle imprese e verifiche comunali. Ogni caso richiede una valutazione specifica.</p></div><div class="feature-columns"><div><span class="pill-n">01 / ACCESSO</span><h3>Prima di iniziare, guarda il contesto.</h3><p>Scale, parcheggio, materiali da movimentare e gestione dei detriti incidono sull’organizzazione dei lavori.</p></div><div><span class="pill-n">02 / EDIFICIO</span><h3>Impianti e condizioni esistenti.</h3><p>Fotografie, rilievi, tracce degli interventi precedenti e stato delle superfici aiutano a ridurre le sorprese.</p></div><div><span class="pill-n">03 / AUTORIZZAZIONI</span><h3>Verifica prima delle demolizioni.</h3><p>La pratica necessaria dipende dal tipo di intervento: per decisioni tecniche e amministrative rivolgiti a un professionista abilitato.</p></div></div></section>
<section class="cta-band"><div class="wrap cta-band-grid"><div>{section_label('05','UN PASSAGGIO ALLA VOLTA')}<h2>Il preventivo migliore è quello che sai leggere.</h2></div><div><p>Impara a riconoscere inclusioni, esclusioni, tempi e condizioni delle offerte.</p><a href="/preventivi/" class="btn btn-light">La guida ai preventivi {icon('arrow')}</a></div></div></section>
<section class="section wrap compact"><div class="section-row">{section_label('06','TRASPARENZA')}<h2>Chi siamo e cosa<br>non facciamo.</h2><div><p>Siamo un progetto editoriale indipendente. Non eseguiamo lavori e non promettiamo sopralluoghi. Quando il collegamento Edilnet sarà attivo, lo dichiareremo chiaramente.</p>{anchor('metodo','Scopri il nostro metodo')}</div></div></section>'''
page('Ristrutturare casa a Formia: guide, costi e preventivi','Guide indipendenti alla ristrutturazione della casa a Formia. Scopri come definire i lavori, valutare costi e confrontare preventivi.',home)

house=header('GUIDA / 01','Ristrutturare casa<br><em>senza partire alla cieca.</em>','Prima del preventivo servono un perimetro preciso, un ordine delle lavorazioni e domande che impediscano equivoci costosi.','RISTRUTTURAZIONE CASA')+'''<div class="wrap article-layout"><article class="article-body"><div class="article-intro"><p>Una ristrutturazione completa è un insieme di scelte collegate. Il rischio più comune non è soltanto un prezzo alto: è confrontare offerte che includono lavori diversi.</p></div><h2 id="prima">01. Prima di chiedere i prezzi</h2><p>Prepara una descrizione delle condizioni attuali e del risultato atteso: stanze coinvolte, presenza di infiltrazioni o umidità, stato di impianti e serramenti, necessità di demolizioni, finiture e vincoli d’accesso.</p>''' +checklist(['Raccogli planimetrie e fotografie aggiornate, se disponibili.','Distingui i lavori indispensabili da quelli opzionali.','Indica se l’abitazione sarà occupata durante i lavori.','Segnala i limiti d’accesso al cantiere e gli orari condominiali.'])+'''<h2 id="fasi">02. Ordine delle lavorazioni</h2><div class="steps"><div><b>01</b><span><strong>Rilievo e progetto</strong><small>Stato dell’immobile, obiettivi e verifiche tecniche.</small></span></div><div><b>02</b><span><strong>Demolizioni e opere preparatorie</strong><small>Interventi definiti dopo aver valutato la fattibilità.</small></span></div><div><b>03</b><span><strong>Impianti e ripristini</strong><small>Coordinamento tra elettrico, idrico, scarichi e superfici.</small></span></div><div><b>04</b><span><strong>Finiture e verifiche</strong><small>Posa, controlli e consegna documentale.</small></span></div></div><h2 id="confronto">03. Come confrontare offerte</h2><p>Chiedi un elenco di lavorazioni e quantità omogeneo, con la distinzione tra manodopera, materiali, oneri aggiuntivi ed esclusioni. Verifica chi coordina il cantiere, come sono gestite le varianti e quali documenti sono consegnati.</p><div class="note"><b>Il dato da non saltare</b><p>Le autorizzazioni e i professionisti necessari dipendono dal progetto concreto. Nessuna guida online può sostituire una verifica tecnica e amministrativa dell’immobile.</p></div><h2 id="localita">04. A Formia e nel Golfo</h2><p>Accessibilità dell’abitazione, logistica dei materiali, presenza di spazi esterni, vincoli edilizi o paesaggistici e condizioni del fabbricato possono cambiare la fattibilità e il costo. Prima di assumere che un intervento sia consentito, chiedi un riscontro al tecnico competente.</p><h2 id="prossimo">Il passo successivo</h2><p>Se hai già definito le lavorazioni, leggi come preparare una richiesta di preventivo comparabile.</p>'''+anchor('preventivi','Come confrontare preventivi','btn btn-primary')+'</article><aside class="toc"><span>IN QUESTA GUIDA</span><a href="#prima">Prima dei prezzi</a><a href="#fasi">Fasi del lavoro</a><a href="#confronto">Confrontare offerte</a><a href="#localita">Il contesto locale</a><a href="#prossimo">Passo successivo</a><div class="aside-card"><b>Serve un punto di partenza?</b><p>Costruisci un quadro delle voci di spesa prima di confrontare offerte.</p><a href="/costi-ristrutturazione/">Esplora i costi ↗</a></div></aside></div>'''
page('Ristrutturare casa a Formia: fasi e guida ai preventivi','Come organizzare una ristrutturazione casa a Formia: checklist, fasi, impianti, lavori edili e confronto dei preventivi.',house,'ristrutturare-casa','ristrutturare-casa')

bath=header('GUIDA / 02','Rifare il bagno.<br><em>Prima le scelte invisibili.</em>','Piastrelle e rubinetti si vedono. Impermeabilizzazione, scarichi e impianti si scoprono troppo spesso dopo. Parti dai dettagli giusti.','RISTRUTTURAZIONE BAGNO')+'''<div class="wrap article-layout"><article class="article-body"><div class="article-intro"><p>Rifare il bagno non significa soltanto cambiare le finiture. Un preventivo affidabile deve chiarire demolizioni, protezioni, lavori impiantistici, ripristini e tempi.</p></div><h2 id="decisioni">01. Quattro decisioni da prendere</h2>'''+checklist(['Mantieni o modifichi la disposizione di sanitari e doccia?','Gli impianti esistenti sono adeguati e verificati?','Che tipo di piatto doccia, box e rivestimento desideri?','Il bagno è l’unico dell’abitazione? Devi prevedere tempi di indisponibilità?'])+'''<h2 id="preventivo-bagno">02. Le voci che devono comparire</h2><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Voce</th><th>Da chiarire</th></tr></thead><tbody><tr><td>Rimozioni</td><td>Sanitari, pavimenti, rivestimenti, trasporto e smaltimento</td></tr><tr><td>Impianti</td><td>Scarichi, alimentazioni, elettrico e certificazioni applicabili</td></tr><tr><td>Impermeabilizzazione</td><td>Superfici protette, materiali, punti critici e modalità di posa</td></tr><tr><td>Finiture</td><td>Superfici, materiali, tagli, stuccature e profili</td></tr><tr><td>Consegna</td><td>Tempi, verifica delle lavorazioni, pulizia ed eventuali esclusioni</td></tr></tbody></table></div><h2 id="costi-bagno">03. Perché due preventivi differiscono</h2><p>Il costo dipende da stato dell’ambiente, modifiche idrauliche, qualità delle finiture, interventi di impermeabilizzazione, accesso al cantiere e demolizioni. Un prezzo unico “al bagno” senza elenco delle opere ha poco valore comparativo.</p><div class="note"><b>Una buona domanda</b><p>«Nel preventivo sono compresi smaltimento, impermeabilizzazione e ripristino completo delle superfici? Se no, quali costi restano esclusi?»</p></div><h2 id="vasca">04. Se vuoi eliminare la vasca</h2><p>Controlla misure utili, quota dello scarico, accessibilità, tenuta dell’acqua e spazio di manovra. Per questo intervento abbiamo preparato una guida specifica.</p>'''+anchor('vasca-in-doccia','Guida da vasca a doccia','btn btn-primary')+'</article><aside class="toc"><span>IN QUESTA GUIDA</span><a href="#decisioni">Prima di scegliere</a><a href="#preventivo-bagno">Voci del preventivo</a><a href="#costi-bagno">Differenze di prezzo</a><a href="#vasca">Da vasca a doccia</a><div class="aside-card"><b>Metti in ordine le voci</b><p>Uno scenario di spesa basato sui valori che inserisci tu.</p><a href="/costi-ristrutturazione/">Apri il simulatore ↗</a></div></aside></div>'''
page('Ristrutturazione bagno a Formia: lavori e preventivi','Ristrutturazione bagno a Formia: cosa include un buon preventivo, quali lavori verificare e come confrontare le offerte.',bath,'ristrutturazione-bagno','ristrutturazione-bagno')

shower=header('GUIDA / 03','Da vasca a doccia.<br><em>Non basta cambiare un pezzo.</em>','Misure, quote, scarichi, tenuta dell’acqua e sicurezza d’uso: cinque elementi da verificare prima di scegliere la soluzione.','SOSTITUZIONE VASCA')+'''<div class="wrap article-layout"><article class="article-body"><div class="article-intro"><p>La sostituzione della vasca con una doccia può migliorare l’uso quotidiano del bagno, ma non è sempre un intervento identico. Gli elementi decisivi sono spesso nascosti sotto i rivestimenti.</p></div><h2 id="controlli">01. I controlli indispensabili</h2>'''+checklist(['Misura la vasca e lo spazio libero attorno, includendo apertura e passaggi.','Verifica con un professionista quote, pendenza e collegamento dello scarico.','Definisci il sistema di impermeabilizzazione delle nuove superfici.','Valuta accesso, soglia, superfici antiscivolo e manutenzione.','Chiarisci ripristino di pareti e pavimento dopo la rimozione.'])+'''<h2 id="soluzioni">02. Come scegliere la soluzione</h2><p>Una doccia filo pavimento richiede condizioni tecniche precise e può non essere fattibile senza interventi importanti. Un piatto ribassato può essere un’alternativa in alcuni casi. La scelta va concordata dopo il rilievo, non promessa da una pagina web.</p><h2 id="cosa-include">03. Cosa deve includere il preventivo</h2><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Intervento</th><th>Verifica</th></tr></thead><tbody><tr><td>Rimozione vasca</td><td>Smontaggio, smaltimento, ripristino sotto vasca</td></tr><tr><td>Scarico</td><td>Compatibilità, quota e pendenza</td></tr><tr><td>Tenuta all’acqua</td><td>Membrane, giunti, sigillature</td></tr><tr><td>Doccia e chiusure</td><td>Dimensioni, accesso, manutenzione</td></tr><tr><td>Rivestimenti</td><td>Superficie ripristinata e abbinamento all’esistente</td></tr></tbody></table></div><h2 id="tempi">04. Quanto tempo serve?</h2><p>Dipende dallo stato dell’impianto, dalla disponibilità dei materiali e dai ripristini necessari. Diffida di tempi identici garantiti senza sopralluogo: chiedi sempre una pianificazione scritta e le condizioni che potrebbero modificarla.</p><div class="note"><b>Per l’accessibilità</b><p>Se l’intervento è legato a mobilità ridotta o autonomia personale, indica i bisogni funzionali specifici. Una soluzione esteticamente pulita non è automaticamente adatta a tutti gli utenti.</p></div>'''+anchor('preventivi','Preparare la richiesta di preventivo','btn btn-primary')+'</article><aside class="toc"><span>IN QUESTA GUIDA</span><a href="#controlli">Cinque controlli</a><a href="#soluzioni">Scelta della doccia</a><a href="#cosa-include">Cosa include</a><a href="#tempi">Tempi e fattibilità</a><div class="aside-card"><b>Progetto più grande?</b><p>Se cambi anche impianti e rivestimenti, leggi la guida completa al bagno.</p><a href="/ristrutturazione-bagno/">Rifare il bagno ↗</a></div></aside></div>'''
page('Da vasca a doccia a Formia: guida alle scelte','Sostituire la vasca con la doccia a Formia: misure, scarico, impermeabilizzazione, accessibilità e voci del preventivo.',shower,'vasca-in-doccia','vasca-in-doccia')

costs=header('STRUMENTO / 04','Quanto costa<br><em>ristrutturare casa?</em>','Nessun prezzo “medio” è un preventivo. Capisci quali variabili incidono sui lavori e costruisci una simulazione con valori scelti da te.','COSTI DI RISTRUTTURAZIONE')+'''<div class="wrap article-layout"><article class="article-body"><div class="article-intro"><p>Le ricerche sul costo al metro quadro sono frequenti, ma il prezzo cambia molto quando cambiano le lavorazioni. Separare le voci è più utile che applicare una media indistinta.</p></div><h2 id="fattori">01. Le variabili principali</h2><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Fattore</th><th>Impatto possibile</th></tr></thead><tbody><tr><td>Stato iniziale</td><td>Demolizioni, ripristini, problemi non visibili</td></tr><tr><td>Impianti</td><td>Interventi parziali o rifacimento di linee e scarichi</td></tr><tr><td>Superficie e quantità</td><td>Metri quadrati, punti impianto, numero ambienti</td></tr><tr><td>Materiali e finiture</td><td>Fornitura, posa e lavorazioni speciali</td></tr><tr><td>Logistica</td><td>Accessi, piano dell’immobile, movimentazione e smaltimento</td></tr></tbody></table></div><h2 id="calcolatore">02. Simulatore di budget</h2><p>Inserisci importi ipotetici ricavati da tue ricerche, stime professionali o offerte preliminari. <strong>Il sito non imposta prezzi al posto tuo.</strong> Il risultato è una somma organizzata, non un preventivo.</p><div class="calculator" id="calculator"><div class="calc-head"><span>WORKSHEET / 01</span><strong>IL TUO SCENARIO</strong></div><div class="calc-grid"><label>Demolizioni e smaltimento <span>€</span><input id="cost-demolitions" type="number" inputmode="decimal" min="0" max="9999999" step="1" placeholder="Importo ipotetico"></label><label>Impianti e ripristini <span>€</span><input id="cost-systems" type="number" inputmode="decimal" min="0" max="9999999" step="1" placeholder="Importo ipotetico"></label><label>Materiali e finiture <span>€</span><input id="cost-finishes" type="number" inputmode="decimal" min="0" max="9999999" step="1" placeholder="Importo ipotetico"></label><label>Altre lavorazioni <span>€</span><input id="cost-other" type="number" inputmode="decimal" min="0" max="9999999" step="1" placeholder="Importo ipotetico"></label><label>Margine per imprevisti <span>%</span><input id="cost-contingency" type="number" inputmode="decimal" min="0" max="100" step="1" placeholder="Percentuale a tua scelta"></label></div><div class="calc-total"><div><small>TOTALE SIMULATO</small><output id="cost-result" aria-live="polite">—</output></div><button type="button" id="calc-reset" class="btn-reset">Azzera ↗</button></div><p class="calc-disclaimer">Calcolo aritmetico su importi inseriti dall’utente. Non include automaticamente IVA, spese tecniche, pratiche o voci non specificate. Nessun dato viene trasmesso o salvato sul server.</p></div><h2 id="prezzi">03. Come leggere un prezzo al m²</h2><p>Una stima al metro quadro può aiutare a definire un ordine di grandezza soltanto se si conosce cosa comprende. Chiedi sempre se include impianti, demolizioni, fornitura delle finiture, smaltimento e spese tecniche. Confrontare valori con perimetri diversi produce conclusioni errate.</p><div class="note"><b>Fonti e dati</b><p>Non pubblichiamo fasce di prezzo locali non documentate. Prima della pubblicazione di benchmark economici serviranno fonti verificabili, date aggiornate e ipotesi chiaramente esposte.</p></div>'''+anchor('preventivi','Come richiedere preventivi comparabili','btn btn-primary')+'</article><aside class="toc"><span>IN QUESTA GUIDA</span><a href="#fattori">Fattori di costo</a><a href="#calcolatore">Simulatore</a><a href="#prezzi">Prezzo al m²</a><div class="aside-card"><b>Quanto costa il bagno?</b><p>Non guardare solo il totale: scopri quali voci devono essere presenti.</p><a href="/ristrutturazione-bagno/">Voci del bagno ↗</a></div></aside></div>'''
page('Quanto costa ristrutturare casa al mq: voci e simulatore','Come valutare il costo di ristrutturazione casa al metro quadro: fattori, voci di spesa e simulatore con importi personalizzati.',costs,'costi-ristrutturazione','costi-ristrutturazione')

quotes=header('STRUMENTO / 05','Un preventivo utile<br><em>è confrontabile.</em>','La cifra finale è soltanto una delle informazioni da leggere. Prima di chiedere offerte, definisci il lavoro in modo che ogni proposta risponda alla stessa domanda.','CONFRONTO PREVENTIVI')+'''<div class="wrap article-layout"><article class="article-body"><div class="article-intro"><p>Il primo obiettivo non è ricevere il maggior numero possibile di numeri, ma confrontare descrizioni complete delle stesse lavorazioni.</p></div><h2 id="prepara">01. Prepara la richiesta</h2>'''+checklist(['Località dell’immobile e tipologia (appartamento, casa, altro).','Tipologia di intervento e ambienti coinvolti.','Dimensioni approssimative e fotografie disponibili.','Lavori desiderati, impianti coinvolti e finiture preferite.','Vincoli d’accesso e tempi indicativi.','Informazioni su eventuali verifiche tecniche o progetti già esistenti.'])+'''<h2 id="leggi">02. Leggi oltre il totale</h2><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Domanda</th><th>Perché conta</th></tr></thead><tbody><tr><td>Che cosa è incluso?</td><td>Due totali diversi possono comprendere opere differenti.</td></tr><tr><td>Che cosa è escluso?</td><td>Materiali, smaltimento e spese tecniche possono essere separati.</td></tr><tr><td>Quali condizioni cambiano il prezzo?</td><td>Le varianti vanno definite e approvate prima di eseguirle.</td></tr><tr><td>Come si documenta la consegna?</td><td>Verifiche, documentazione e garanzie vanno chiarite.</td></tr></tbody></table></div><h2 id="partner">03. Il collegamento ai preventivi</h2><div class="partner-panel"><p class="partner-kicker">PARTNER PREVENTIVI / IN CONFIGURAZIONE</p><h3>Richieste gratuite tramite Edilnet.</h3><p>Quando l’attivazione sarà completata, potrai passare al sito Edilnet per inviare direttamente una richiesta. Edilnet gestisce il servizio e le informazioni raccolte sul proprio sito. Ristrutturazioni Formia non raccoglierà i tuoi contatti tramite questo percorso.</p><button type="button" disabled aria-disabled="true" class="btn btn-disabled">Collegamento in attivazione</button><small>Non abbiamo ancora inserito il link affiliato. Nessuna richiesta viene inoltrata da questa anteprima.</small></div><h2 id="trasparenza">04. La trasparenza del rapporto</h2><p>Ristrutturazioni Formia è un progetto editoriale indipendente e non esegue lavori. Una volta attivo il link, potremmo ricevere una commissione per le richieste valide generate tramite l’affiliazione Edilnet. Questa collaborazione deve essere riconoscibile prima del click.</p></article><aside class="toc"><span>IN QUESTA GUIDA</span><a href="#prepara">Prepara la richiesta</a><a href="#leggi">Leggi le offerte</a><a href="#partner">Il partner</a><a href="#trasparenza">Trasparenza</a><div class="aside-card"><b>Non sai ancora cosa chiedere?</b><p>Parti dalla guida alla ristrutturazione completa.</p><a href="/ristrutturare-casa/">Inizia da qui ↗</a></div></aside></div>'''
page('Preventivi ristrutturazione a Formia: guida al confronto','Come preparare una richiesta e confrontare preventivi per ristrutturare casa o bagno a Formia. Edilnet sarà il partner delle richieste.',quotes,'preventivi')

method=header('PROGETTO / 06','Informare prima<br><em>di convincere.</em>','Il nostro metodo parte da una distinzione chiara: siamo un progetto editoriale, non un’impresa di ristrutturazioni.','IL NOSTRO METODO')+'''<div class="wrap article-layout"><article class="article-body"><div class="article-intro"><p>Ristrutturazioni Formia raccoglie guide, checklist e strumenti informativi per aiutare le persone a descrivere meglio i lavori da eseguire e a valutare le proposte ricevute.</p></div><h2>Che cosa facciamo</h2>'''+checklist(['Organizziamo le informazioni per progetto e intenzione di ricerca.','Spieghiamo le voci tecniche e commerciali che conviene chiarire.','Distinguiamo esempi, ipotesi e dati verificati.','Aggiorniamo i contenuti quando cambiano norme o fonti rilevanti.'])+'''<h2>Che cosa non facciamo</h2><p>Non siamo un’impresa edile. Non effettuiamo sopralluoghi, non eseguiamo lavori e non rilasciamo pareri professionali sostitutivi di quelli di tecnici abilitati. Non pubblichiamo recensioni, testimonianze o risultati di cantiere non verificati.</p><h2>Perché Edilnet</h2><p>La richiesta di preventivi potrà essere gestita da Edilnet, un soggetto esterno identificato in modo trasparente. L’eventuale commissione affiliata non sarà nascosta all’utente. Il collegamento è ancora in configurazione in questa anteprima.</p><h2>Le fonti</h2><p>Per contenuti che cambiano nel tempo, come incentivi e procedure, privilegiamo documentazione istituzionale aggiornata e indichiamo la necessità di una verifica professionale sul caso concreto. Il nostro archivio di ricerca keyword serve a capire le domande delle persone, non a fabbricare numeri o affermazioni tecniche.</p>'''+anchor('preventivi','Come funziona il percorso preventivi','btn btn-primary')+'</article><aside class="toc"><span>REGOLE EDITORIALI</span><div class="aside-card"><b>Il principio</b><p>Promesse misurabili. Fonti dichiarate. Nessun ruolo professionale simulato.</p></div></aside></div>'''
page('Metodo editoriale e trasparenza','Il metodo di Ristrutturazioni Formia: guide indipendenti, informazioni verificabili e trasparenza sull’affiliazione Edilnet.',method,'metodo')

privacy=header('INFORMAZIONI','Privacy di questa<br><em>anteprima.</em>','Questa pagina descrive il funzionamento della sola versione dimostrativa. Non è ancora l’informativa definitiva del sito pubblico.','PRIVACY / DEMO')+'''<div class="wrap article-layout"><article class="article-body"><div class="article-intro"><p>Questa anteprima funziona tramite file HTML, CSS e JavaScript statici. Non contiene moduli di contatto o sistemi attivi di registrazione utenti.</p></div><h2>Dati inseriti nel simulatore</h2><p>I valori del simulatore sono elaborati localmente nel browser. Non sono inviati a un server e non vengono registrati da questa applicazione.</p><h2>Strumenti terzi</h2><p>La versione dimostrativa non integra sistemi di analytics, strumenti pubblicitari o link affiliati attivi. L’hosting, qualora il sito venga pubblicato, potrà comunque trattare dati tecnici di accesso secondo le proprie politiche.</p><h2>Prima della pubblicazione</h2><p>La futura informativa dovrà identificare il titolare, i contatti, le finalità del trattamento, gli eventuali fornitori e le basi giuridiche applicabili. Questa pagina non deve essere utilizzata come informativa di produzione prima del completamento delle verifiche.</p></article><aside class="toc"><span>STATO</span><div class="aside-card"><b>Anteprima non pubblicata</b><p>Nessun modulo di acquisizione contatti e nessun collegamento Edilnet attivo.</p></div></aside></div>'''
page('Privacy della preview','Come vengono gestiti i dati nella versione dimostrativa di Ristrutturazioni Formia e quali verifiche restano prima della pubblicazione.',privacy,'privacy')

(OUT/'404.html').write_text(page_404 := '<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="robots" content="noindex"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/assets/site.css"><title>Pagina non trovata | Ristrutturazioni Formia</title></head><body><main class="wrap not-found"><p class="eyebrow">ERRORE / 404</p><h1>Questa pagina non c’è.</h1><p>Torna alla guida iniziale o scegli un percorso.</p><a href="/" class="btn btn-primary">Torna alla home →</a></main></body></html>',encoding='utf-8')
(OUT/'robots.txt').write_text('User-agent: *\nDisallow: /\n# PREVIEW ONLY. Remove Disallow after final launch QA.\n',encoding='utf-8')
(OUT/'_headers').write_text('/*\n  X-Robots-Tag: noindex, nofollow\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n  Permissions-Policy: camera=(), microphone=(), geolocation=()\n',encoding='utf-8')
